//! thermal.resource's functions: the board's temperatures, as its sensors
//! last read them, and who is told when one runs hot. A resource: no Open
//! or Close, its first function in the first slot. The base comes from
//! OpenResource("thermal.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/thermal_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const exec = @import("../libs/exec/exec.zig");
const thermal = @import("../resources/thermal.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "thermal.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const ReadTemperature = libraries.lvo(0);
    pub const AddThermalNotify = libraries.lvo(1);
    pub const RemThermalNotify = libraries.lvo(2);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const ReadTemperature = *const fn (*ThermalBase, u32, *thermal.ThermalState) callconv(.c) bool;
    pub const AddThermalNotify = *const fn (*ThermalBase, *exec.Task, u32) callconv(.c) ?*thermal.ThermalNotify;
    pub const RemThermalNotify = *const fn (*ThermalBase, ?*thermal.ThermalNotify) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const ThermalBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *ThermalBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Sensor `unit` as last read, into `state`: unit 0 is the board's first.
    /// False if the board has no such sensor, or it has given no reading yet.
    pub fn ReadTemperature(self: *ThermalBase, unit: u32, state: *thermal.ThermalState) bool {
        return libraries.call(self, LVO.ReadTemperature, Fn.ReadTemperature, .{ unit, state });
    }

    /// `signals` sent to `task` whenever a sensor's reading passes its hot or
    /// its critical temperature, either way; null without memory.
    pub fn AddThermalNotify(self: *ThermalBase, task: *exec.Task, signals: u32) ?*thermal.ThermalNotify {
        return libraries.call(self, LVO.AddThermalNotify, Fn.AddThermalNotify, .{ task, signals });
    }

    /// No more of that.
    pub fn RemThermalNotify(self: *ThermalBase, notify: ?*thermal.ThermalNotify) void {
        return libraries.call(self, LVO.RemThermalNotify, Fn.RemThermalNotify, .{notify});
    }
};
